# ==============================================================================
# RESOLUCAO E PROTOCOLO ESTRITO DA FERRAMENTA DE TRABALHO (RAI CLI)
# 1. Raiz: Override em ~/.squad-ai/destinos.json -> Windows %LOCALAPPDATA%\RAI\CLI -> Unix ~/.resolveai
# 2. Regra: NUNCA criar a pasta raiz se nao existir na maquina. So instalar se detectada.
# 3. Manifesto e backups FORA de skills/ (em ~/.squad-ai/instalacoes/rai/).
# 4. Porta de seguranca: nao sobrescrever skill pessoal/terceiros sem --force.
# ==============================================================================
resolve_rai_root() {
  local destinos_file="${SQUAD_USER_DIR}/destinos.json"
  if [[ -f "${destinos_file}" ]]; then
    local custom_raiz
    custom_raiz="$(grep -Eo '"raiz"[[:space:]]*:[[:space:]]*"[^"]+"' "${destinos_file}" 2>/dev/null | head -n 1 | sed -E 's/.*"raiz"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/' || true)"
    if [[ -n "${custom_raiz}" ]]; then
      if command -v cygpath >/dev/null 2>&1 && [[ "${custom_raiz}" == *":"* ]]; then
        custom_raiz="$(cygpath -u "${custom_raiz}" 2>/dev/null || echo "${custom_raiz}")"
      fi
      echo "${custom_raiz}"
      return 0
    fi
  fi

  local win_local="${LOCALAPPDATA:-}"
  if [[ -n "${win_local}" ]] && command -v cygpath >/dev/null 2>&1; then
    win_local="$(cygpath -u "${win_local}" 2>/dev/null || echo "${win_local}")"
  fi
  if [[ -n "${win_local}" && "${win_local}" != "${USER_HOME}"* ]]; then
    win_local=""
  fi
  if [[ -z "${win_local}" && -d "${USER_HOME}/AppData/Local" ]]; then
    win_local="${USER_HOME}/AppData/Local"
  fi

  if [[ -n "${win_local}" ]]; then
    if [[ -d "${win_local}/RAI/CLI" ]]; then
      echo "${win_local}/RAI/CLI"
      return 0
    fi
    if [[ -d "${USER_HOME}/.resolveai" ]]; then
      echo "${USER_HOME}/.resolveai"
      return 0
    fi
    echo "${win_local}/RAI/CLI"
    return 0
  fi

  echo "${USER_HOME}/.resolveai"
}

