unwrap_offline_slot_key_256() {
  local wrapped_hex="$1"
  local realm_low
  realm_low="$(printf '%s' "$2" | tr '[:upper:]' '[:lower:]')"
  local key_id_up
  key_id_up="$(printf '%s' "$3" | tr '[:lower:]' '[:upper:]')"
  local secret_key_up
  secret_key_up="$(printf '%s' "$4" | tr '[:lower:]' '[:upper:]')"
  local mask_hex
  if command -v sha256sum >/dev/null 2>&1; then
    mask_hex="$(printf 'SQUAD-OFFLINE-KEY-WRAP-V1|%s|%s|%s' "${realm_low}" "${key_id_up}" "${secret_key_up}" | sha256sum | awk '{print tolower($1)}')"
  else
    mask_hex="$(printf 'SQUAD-OFFLINE-KEY-WRAP-V1|%s|%s|%s' "${realm_low}" "${key_id_up}" "${secret_key_up}" | shasum -a 256 | awk '{print tolower($1)}')"
  fi
  local out=""
  local i
  for ((i=0; i<64; i+=8)); do
    local w_chunk="${wrapped_hex:i:8}"
    local m_chunk="${mask_hex:i:8}"
    local x_val=$(( (16#${w_chunk} ^ 16#${m_chunk}) & 0xFFFFFFFF ))
    out="${out}$(printf '%08x' "${x_val}")"
  done
  printf '%s' "${out}"
}

xor_station_bound_key_256() {
  local key_hex="$1"
  local qid_up
  qid_up="$(printf '%s' "$2" | tr '[:lower:]' '[:upper:]')"
  local realm_low
  realm_low="$(printf '%s' "$3" | tr '[:upper:]' '[:lower:]')"
  local key_id_up
  key_id_up="$(printf '%s' "$4" | tr '[:lower:]' '[:upper:]')"
  local mask_hex
  if command -v sha256sum >/dev/null 2>&1; then
    mask_hex="$(printf 'SQUAD-LOCAL-STATION-BIND-V1|%s|%s|%s' "${qid_up}" "${realm_low}" "${key_id_up}" | sha256sum | awk '{print tolower($1)}')"
  else
    mask_hex="$(printf 'SQUAD-LOCAL-STATION-BIND-V1|%s|%s|%s' "${qid_up}" "${realm_low}" "${key_id_up}" | shasum -a 256 | awk '{print tolower($1)}')"
  fi
  local out=""
  local i
  for ((i=0; i<64; i+=8)); do
    local w_chunk="${key_hex:i:8}"
    local m_chunk="${mask_hex:i:8}"
    local x_val=$(( (16#${w_chunk} ^ 16#${m_chunk}) & 0xFFFFFFFF ))
    out="${out}$(printf '%08x' "${x_val}")"
  done
  printf '%s' "${out}"
}

authorize_with_control_plane() {
  UNWRAPPED_CATALOG_KEY=""
  LICENSE_ID_ISSUED=""
  LICENSE_KEY_ID_ISSUED=""
  LICENSE_SEATS_SUMMARY=""
  if [[ ${IS_AUDIT_SANDBOX} -eq 1 ]]; then
    return 0
  fi

  local self_path="${BASH_SOURCE[0]}"
  AUTH_EMAIL="$(printf '%s' "${AUTH_EMAIL}" | tr -d ' \t\r\n')"
  ACTIVATION_PIN="$(printf '%s' "${ACTIVATION_PIN}" | tr -d ' \t\r\n')"

  local saved_email=""
  local saved_key_id=""
  local saved_station_bound=""
  local saved_station_qid=""
  if [[ -f "${SQUAD_USER_DIR}/station-profile.json" ]]; then
    saved_email="$(grep -Eo '"email"[[:space:]]*:[[:space:]]*"[^"]+"' "${SQUAD_USER_DIR}/station-profile.json" 2>/dev/null | head -n 1 | sed -E 's/.*"email"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/' || true)"
    if [[ "${saved_email}" == "dev@empresa.com" ]]; then
      saved_email=""
    fi
  fi
  if [[ -f "${SQUAD_USER_DIR}/license.json" ]]; then
    saved_key_id="$(grep -Eo '"license_key_id"[[:space:]]*:[[:space:]]*"[^"]+"' "${SQUAD_USER_DIR}/license.json" 2>/dev/null | head -n 1 | sed -E 's/.*"license_key_id"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/' || true)"
    saved_station_bound="$(grep -Eo '"station_bound_key"[[:space:]]*:[[:space:]]*"[0-9a-fA-F]{64}"' "${SQUAD_USER_DIR}/license.json" 2>/dev/null | head -n 1 | sed -E 's/.*"([0-9a-fA-F]{64})".*/\1/' || true)"
    saved_station_qid="$(grep -Eo '"station_qid"[[:space:]]*:[[:space:]]*"[^"]+"' "${SQUAD_USER_DIR}/license.json" 2>/dev/null | head -n 1 | sed -E 's/.*"station_qid"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/' || true)"
  fi

  if [[ -z "${AUTH_EMAIL}" && -t 0 ]]; then
    local default_email="${saved_email:-${USER_NAME}@${REALM}.local}"
    local typed_email=""
    echo ""
    read -r -p "  Informe o e-mail do desenvolvedor [ENTER = ${default_email}]: " typed_email || typed_email=""
    typed_email="$(printf '%s' "${typed_email}" | tr -d ' \t\r\n')"
    if [[ -n "${typed_email}" ]]; then
      AUTH_EMAIL="${typed_email}"
    else
      AUTH_EMAIL="${default_email}"
    fi
  elif [[ -z "${AUTH_EMAIL}" ]]; then
    AUTH_EMAIL="${saved_email:-${USER_NAME}@${REALM}.local}"
  fi

  if [[ -z "${ACTIVATION_PIN}" && -t 0 ]]; then
    if [[ -n "${saved_key_id}" && "${saved_station_qid}" == "${QID}" && ${#saved_station_bound} -eq 64 ]]; then
      read -r -p "  Informe sua Chave de Licenca Individual liberada [ENTER = manter ${saved_key_id}]: " ACTIVATION_PIN || ACTIVATION_PIN=""
    else
      read -r -p "  Informe sua Chave de Licenca Individual liberada (ex.: SQKEY-ENT-01-...): " ACTIVATION_PIN || ACTIVATION_PIN=""
    fi
    ACTIVATION_PIN="$(printf '%s' "${ACTIVATION_PIN}" | tr -d ' \t\r\n')"
  fi

  local realm_low
  realm_low="$(printf '%s' "${REALM}" | tr '[:upper:]' '[:lower:]')"

  # Reutilizar chave ja vinculada a esta mesma estacao (QID) caso o usuario tecle ENTER no reinstall
  if [[ -z "${ACTIVATION_PIN}" && -n "${saved_key_id}" && "${saved_station_qid}" == "${QID}" && ${#saved_station_bound} -eq 64 ]]; then
    UNWRAPPED_CATALOG_KEY="$(xor_station_bound_key_256 "${saved_station_bound}" "${QID}" "${realm_low}" "${saved_key_id}")"
    LICENSE_KEY_ID_ISSUED="${saved_key_id}"
    local slot_num_saved="${saved_key_id##*-}"
    LICENSE_ID_ISSUED="LIC-OFFLINE-${saved_key_id}-${QID:9:9}"
    LICENSE_SEATS_SUMMARY="SLOT #${slot_num_saved}/10 (LIBERACAO OFFLINE)"
    return 0
  fi

  if [[ -z "${ACTIVATION_PIN}" ]]; then
    echo ""
    echo "${C_BOLD}${C_RED}  [BLOQUEADO] ERR_LICENSE_KEY_REQUIRED: Chave de Licenca Individual obrigatoria!${C_RESET}"
    echo "  Informe uma das 10 chaves individuais liberadas para o dominio '${REALM}' (100% Offline, sem servidor):"
    echo "    ${C_CYAN}bash ./setup-squad-ai-windows.sh --install --email seu@email.com --pin SQKEY-ENT-XX-XXXX-XXXX-XXXX${C_RESET}"
    return 1
  fi

  ACTIVATION_PIN="$(printf '%s' "${ACTIVATION_PIN}" | tr '[:lower:]' '[:upper:]')"

  local verifier_hex=""
  if command -v sha256sum >/dev/null 2>&1; then
    verifier_hex="$(printf 'SQUAD-OFFLINE-KEY-VERIFY-V1|%s|%s' "${realm_low}" "${ACTIVATION_PIN}" | sha256sum | awk '{print tolower($1)}')"
  else
    verifier_hex="$(printf 'SQUAD-OFFLINE-KEY-VERIFY-V1|%s|%s' "${realm_low}" "${ACTIVATION_PIN}" | shasum -a 256 | awk '{print tolower($1)}')"
  fi

  local matched_slot_line=""
  if grep -q "^__SQUAD_SKILLS_ARCHIVE_BELOW__$" "${self_path}" 2>/dev/null; then
    matched_slot_line="$(sed '1,/^__SQUAD_SKILLS_ARCHIVE_BELOW__$/d' "${self_path}" | grep '^ENC_SLOT_' | grep -i ":${verifier_hex}:" | head -n 1 | tr -d ' \t\r\n' || true)"
  fi

  if [[ -z "${matched_slot_line}" ]]; then
    echo ""
    echo "${C_BOLD}${C_RED}  [ACESSO NEGADO — VALIDACAO DE LICENCA OFFLINE (${REALM})]${C_RESET}"
    echo "  E-mail Solicitante : ${AUTH_EMAIL}"
    echo "  Estacao / QID      : ${HOST_NAME} (${QID})"
    echo "  Motivo do Bloqueio : ERR_INVALID_OFFLINE_LICENSE_KEY: Chave individual invalida para o dominio '${REALM}'."
    echo "  Dica               : Utilize uma das 10 chaves pre-liberadas (SQKEY-ENT-01-... a SQKEY-ENT-10-...)."
    return 1
  fi

  # Formato: ENC_SLOT_02=SQKEY-ENT-02:<verifier_sha256>:<wrapped_master_key>
  local slot_header="${matched_slot_line%%=*}"
  local slot_num="${slot_header#ENC_SLOT_}"
  local slot_rhs="${matched_slot_line#*=}"
  local slot_key_id="${slot_rhs%%:*}"
  local slot_wrapped_key="${slot_rhs##*:}"

  UNWRAPPED_CATALOG_KEY="$(unwrap_offline_slot_key_256 "${slot_wrapped_key}" "${realm_low}" "${slot_key_id}" "${ACTIVATION_PIN}")"
  if [[ ${#UNWRAPPED_CATALOG_KEY} -ne 64 ]]; then
    echo ""
    echo "${C_BOLD}${C_RED}  [ERRO CRIPTOGRAFICO] Falha ao desencapsular a chave mestra AES-256 do slot offline ${slot_key_id}.${C_RESET}"
    return 1
  fi

  LICENSE_KEY_ID_ISSUED="${slot_key_id}"
  LICENSE_ID_ISSUED="LIC-OFFLINE-${slot_key_id}-${QID:9:9}"
  LICENSE_SEATS_SUMMARY="SLOT #${slot_num}/10 (LIBERACAO OFFLINE)"

  local station_bound_hex
  station_bound_hex="$(xor_station_bound_key_256 "${UNWRAPPED_CATALOG_KEY}" "${QID}" "${realm_low}" "${slot_key_id}")"
  local now_iso
  now_iso="$(date -u +"%Y-%m-%dT%H:%M:%SZ" 2>/dev/null || echo "2026-11-04T18:00:00Z")"

  mkdir -p "${SQUAD_USER_DIR}"
  cat > "${SQUAD_USER_DIR}/license.json" <<EOF
{
  "allowed": true,
  "activation_mode": "OFFLINE_PRE_RELEASED_KEY",
  "server_required": false,
  "realm_id": "${REALM}",
  "license_id": "${LICENSE_ID_ISSUED}",
  "license_key_id": "${LICENSE_KEY_ID_ISSUED}",
  "license_key_slot": ${slot_num#0},
  "email": "${AUTH_EMAIL}",
  "station_qid": "${QID}",
  "station_id": "${HOST_NAME}",
  "team_squad": "${SQUAD_TEAM}",
  "status": "ACTIVE",
  "activated_at_utc": "${now_iso}",
  "cipher_suite": "AES-256-CBC-PBKDF2-HMAC-SHA256 + OFFLINE-KEY-SLOT-V1",
  "station_bound_key": "${station_bound_hex}"
}
EOF
  return 0
}

extract_embedded_skills_payload() {
  local self_path="${BASH_SOURCE[0]}"
  CATALOG_SKILLS_DIR="${SQUAD_USER_DIR}/catalog/skills"
  rm -rf "${CATALOG_SKILLS_DIR}" 2>/dev/null || true
  if [[ ${IS_AUDIT_SANDBOX} -eq 1 ]]; then
    EMBEDDED_SKILLS_READY=0
    return 1
  fi
  if [[ ${#UNWRAPPED_CATALOG_KEY} -ne 64 ]]; then
    EMBEDDED_SKILLS_READY=0
    return 1
  fi
  if ! command -v openssl >/dev/null 2>&1; then
    echo "${C_RED}  [ERRO] OpenSSL nao encontrado no ambiente para descriptografar o catalogo AES-256.${C_RESET}"
    EMBEDDED_SKILLS_READY=0
    return 1
  fi
  if grep -q "^__SQUAD_SKILLS_ARCHIVE_BELOW__$" "${self_path}" 2>/dev/null; then
    local expected_hmac=""
    expected_hmac="$(sed '1,/^__SQUAD_SKILLS_ARCHIVE_BELOW__$/d' "${self_path}" | grep '^ENC_HMAC_SHA256=' | head -n 1 | cut -d'=' -f2 | tr -d ' \t\r\n' | tr '[:upper:]' '[:lower:]')"
    local tmp_enc
    tmp_enc="$(mktemp 2>/dev/null || echo "${TMPDIR:-/tmp}/squad-enc-payload-$$")"
    sed '1,/^__SQUAD_SKILLS_ARCHIVE_BELOW__$/d' "${self_path}" | grep -v '^ENC_' | (base64 -d 2>/dev/null || base64 -D 2>/dev/null) > "${tmp_enc}"

    local actual_hmac=""
    actual_hmac="$(openssl dgst -sha256 -hmac "${UNWRAPPED_CATALOG_KEY}" "${tmp_enc}" 2>/dev/null | awk '{print tolower($NF)}')"
    if [[ -z "${expected_hmac}" || "${actual_hmac}" != "${expected_hmac}" ]]; then
      rm -f "${tmp_enc}" 2>/dev/null || true
      UNWRAPPED_CATALOG_KEY=""
      echo "${C_RED}  [ERRO CRIPTOGRAFICO] Falha na verificacao de integridade HMAC-SHA256 do pacote cifrado!${C_RESET}"
      EMBEDDED_SKILLS_READY=0
      return 1
    fi

    mkdir -p "${CATALOG_SKILLS_DIR}"
    if openssl enc -d -aes-256-cbc -pbkdf2 -iter 100000 -md sha256 -pass "pass:${UNWRAPPED_CATALOG_KEY}" -in "${tmp_enc}" 2>/dev/null | tar -xzf - -C "${CATALOG_SKILLS_DIR}" 2>/dev/null; then
      rm -f "${tmp_enc}" 2>/dev/null || true
      UNWRAPPED_CATALOG_KEY=""
      if [[ -f "${CATALOG_SKILLS_DIR}/squad-ai/SKILL.md" ]]; then
        EMBEDDED_SKILLS_READY=1
        return 0
      fi
    fi
    rm -f "${tmp_enc}" 2>/dev/null || true
  fi
  UNWRAPPED_CATALOG_KEY=""
  EMBEDDED_SKILLS_READY=0
  return 1
}

provision_target_skills() {
  local target_root="$1"
  local skills_dir="${target_root}/skills"
  mkdir -p "${skills_dir}"

  LAST_NEW_FILES=0
  LAST_PRESERVED_FILES=0
  LAST_EXTRA_INFO="-"

  # Proteger skills pessoais do dev que porventura tenham mesmo nome de skill do catalogo
  local -a personal_colliding=()
  local tmp_preserve="${SQUAD_USER_DIR}/.tmp_preserve_$$"
  if [[ ${FORCE_OVERWRITE} -eq 0 ]]; then
    for sk in "${SKILLS_CATALOG[@]}"; do
      local sfile="${skills_dir}/${sk}/SKILL.md"
      if [[ -f "${sfile}" ]]; then
        local stxt
        stxt="$(<"${sfile}")"
        if [[ "${stxt}" != *"origin: squad-ai"* && "${stxt}" != *"SquadAI Harness"* && "${stxt}" != *"Linha de Defesa de Prompt"* ]]; then
          mkdir -p "${tmp_preserve}/${sk}"
          cp -rf "${skills_dir}/${sk}/." "${tmp_preserve}/${sk}/" 2>/dev/null || true
          personal_colliding+=("${sk}")
          LAST_PRESERVED_FILES=$((LAST_PRESERVED_FILES + 1))
        fi
      fi
    done
  fi

  if [[ ${EMBEDDED_SKILLS_READY} -eq 1 && -d "${CATALOG_SKILLS_DIR}/squad-ai" ]]; then
    cp -rf "${CATALOG_SKILLS_DIR}/." "${skills_dir}/" 2>/dev/null || true
    LAST_NEW_FILES=$(( ${#SKILLS_CATALOG[@]} - ${#personal_colliding[@]} ))
  elif [[ ${IS_AUDIT_SANDBOX} -eq 1 ]]; then
    (cd "${skills_dir}" && mkdir -p "${SKILLS_CATALOG[@]}")
    for sk in "${SKILLS_CATALOG[@]}"; do
      local sfile="${skills_dir}/${sk}/SKILL.md"
      printf '%s\n' "---" "name: ${sk}" "origin: squad-ai" "---" "# Sandbox Audit Marker" > "${sfile}"
      LAST_NEW_FILES=$((LAST_NEW_FILES + 1))
    done
  else
    return 1
  fi

  if [[ ${#personal_colliding[@]} -gt 0 ]]; then
    for sk in "${personal_colliding[@]}"; do
      rm -rf "${skills_dir}/${sk}"
      mkdir -p "${skills_dir}/${sk}"
      cp -rf "${tmp_preserve}/${sk}/." "${skills_dir}/${sk}/" 2>/dev/null || true
    done
    rm -rf "${tmp_preserve}"
  fi

  if [[ "${target_root}" == *".copilot" ]]; then
    if [[ ! -f "${target_root}/copilot-instructions.md" ]]; then
      cat > "${target_root}/copilot-instructions.md" <<EOF
# SquadAI Harness v1.0.113 — Instrucoes para GitHub Copilot Agent

- **Versao Sincronizada:** \`v1.0.113\` (\`113\` skills ativas em \`~/.copilot/skills\`)
- **Identificador (QID):** \`${QID}\`
- **Arbitragem Tecnica:** \`P1 Simplicidade > P2 Performance > P3 Custo Baixo\` (Seguranca bloqueante).
EOF
    fi
    LAST_EXTRA_INFO="copilot-instructions.md ativo"
  elif [[ "${target_root}" == *".claude" ]]; then
    LAST_EXTRA_INFO="skills + commands ativos"
  else
    LAST_EXTRA_INFO="catalogo MCP sincronizado"
  fi

  echo "${QID}" > "${skills_dir}/.squad-ai-managed"
}

# Fluxo dedicado de instalacao na ferramenta de trabalho (RAI CLI)
RAI_NEW_COUNT=0
RAI_UPDATED_COUNT=0
RAI_IDENTICAL_COUNT=0
RAI_BLOCKED_COUNT=0

provision_rai_target() {
  local rai_root
  rai_root="$(resolve_rai_root)"
  RAI_NEW_COUNT=0
  RAI_UPDATED_COUNT=0
  RAI_IDENTICAL_COUNT=0
  RAI_BLOCKED_COUNT=0

  # Regra 1 e 4: NAO criar a pasta raiz se nao existir na maquina
  if [[ ! -d "${rai_root}" ]]; then
    return 1
  fi

  local rai_skills="${rai_root}/skills"
  mkdir -p "${rai_skills}"
  rm -f "${rai_skills}/.squad-ai-managed" "${rai_root}/.squad-ai-manifest.json" 2>/dev/null || true

  local rai_meta_dir="${SQUAD_USER_DIR}/instalacoes/rai"
  local rai_manifest="${rai_meta_dir}/manifest.json"
  local ts
  ts="$(date -u +"%Y%m%dT%H%M%SZ" 2>/dev/null || echo "20261101T000000Z")"
  local rai_backup_dir="${rai_meta_dir}/backups/${ts}"
  mkdir -p "${rai_meta_dir}"

  # Fonte completa de skills (prioriza payload embarcado extraido em ~/.squad-ai/catalog/skills)
  local full_source_dir=""
  if [[ ${EMBEDDED_SKILLS_READY} -eq 1 && -d "${CATALOG_SKILLS_DIR}/squad-ai" ]]; then
    full_source_dir="${CATALOG_SKILLS_DIR}"
  elif [[ -d "${USER_HOME}/.claude/skills/squad-ai" ]] && [[ $(wc -c < "${USER_HOME}/.claude/skills/squad-ai/SKILL.md" 2>/dev/null || echo 0) -gt 1000 ]]; then
    full_source_dir="${USER_HOME}/.claude/skills"
  fi

  local existing_count=0
  for sk in "${SKILLS_CATALOG[@]}"; do
    if [[ -f "${rai_skills}/${sk}/SKILL.md" || -f "${rai_skills}/${sk}/RESOLVE_SKILL_${sk}.json" ]]; then
      existing_count=$((existing_count + 1))
    fi
  done

  if [[ ${existing_count} -eq 0 && -n "${full_source_dir}" ]]; then
    cp -rf "${full_source_dir}/." "${rai_skills}/" 2>/dev/null || true
    RAI_NEW_COUNT="${#SKILLS_CATALOG[@]}"
  else
    local manifest_content=""
    if [[ -f "${rai_manifest}" ]]; then
      manifest_content="$(<"${rai_manifest}")"
    fi
    for sk in "${SKILLS_CATALOG[@]}"; do
      local dst_dir="${rai_skills}/${sk}"
      local dst_md="${dst_dir}/SKILL.md"
      local is_new=0
      local existing_md=""
      if [[ ! -f "${dst_md}" && ! -f "${dst_dir}/RESOLVE_SKILL_${sk}.json" ]]; then
        is_new=1
      elif [[ -f "${dst_md}" ]]; then
        existing_md="$(<"${dst_md}")"
      fi

      # Porta de seguranca: se ja existe, verificar se e gerenciada pelo SquadAI
      if [[ ${is_new} -eq 0 && ${FORCE_OVERWRITE} -eq 0 ]]; then
        local is_managed=0
        if [[ "${existing_md}" == *"origin: squad-ai"* || "${existing_md}" == *"SquadAI Harness"* || "${existing_md}" == *"Linha de Defesa de Prompt"* ]]; then
          is_managed=1
        elif [[ "${manifest_content}" == *"\"${sk}\""* ]]; then
          is_managed=1
        fi
        if [[ ${is_managed} -eq 0 ]]; then
          RAI_BLOCKED_COUNT=$((RAI_BLOCKED_COUNT + 1))
          continue
        fi
      fi

      mkdir -p "${dst_dir}"
      if [[ -n "${full_source_dir}" && -f "${full_source_dir}/${sk}/SKILL.md" ]]; then
        local src_md=""
        src_md="$(<"${full_source_dir}/${sk}/SKILL.md")"
        if [[ "${src_md}" != *"name:"* || "${src_md}" != *"description:"* ]]; then
          RAI_BLOCKED_COUNT=$((RAI_BLOCKED_COUNT + 1))
          continue
        fi
        if [[ ${is_new} -eq 1 ]]; then
          cp -rf "${full_source_dir}/${sk}/." "${dst_dir}/" 2>/dev/null || true
          RAI_NEW_COUNT=$((RAI_NEW_COUNT + 1))
        elif [[ "${existing_md}" == "${src_md}" ]]; then
          RAI_IDENTICAL_COUNT=$((RAI_IDENTICAL_COUNT + 1))
        else
          mkdir -p "${rai_backup_dir}/${sk}"
          cp -f "${dst_md}" "${rai_backup_dir}/${sk}/SKILL.md" 2>/dev/null || true
          cp -rf "${full_source_dir}/${sk}/." "${dst_dir}/" 2>/dev/null || true
          RAI_UPDATED_COUNT=$((RAI_UPDATED_COUNT + 1))
        fi
      elif [[ ${IS_AUDIT_SANDBOX} -eq 1 ]]; then
        local stub_md="---
name: ${sk}
origin: squad-ai
---
# Sandbox Audit Marker"
        if [[ ${is_new} -eq 1 ]]; then
          printf '%s\n' "${stub_md}" > "${dst_md}"
          RAI_NEW_COUNT=$((RAI_NEW_COUNT + 1))
        else
          RAI_IDENTICAL_COUNT=$((RAI_IDENTICAL_COUNT + 1))
        fi
      fi
    done
  fi

  # Gravar manifesto FORA de <raiz>/skills/ (em ~/.squad-ai/instalacoes/rai/manifest.json)
  cat > "${rai_manifest}" <<EOF
{
  "schema": 1,
  "installed_at": "${ts}",
  "target_root": "${rai_root}",
  "skills_dir": "${rai_skills}",
  "nova_count": ${RAI_NEW_COUNT},
  "atualizada_count": ${RAI_UPDATED_COUNT},
  "identica_count": ${RAI_IDENTICAL_COUNT},
  "bloqueada_count": ${RAI_BLOCKED_COUNT},
  "managed_by": "squad-ai-harness-v1.0.113"
}
EOF
  return 0
}

LAST_REMOVED_SKILLS_COUNT=0
LAST_PRESERVED_DEV_SKILLS_COUNT=0

remove_squad_skills_from_dir() {
  local skills_dir="$1"
  local is_rai="${2:-0}"
  LAST_REMOVED_SKILLS_COUNT=0
  LAST_PRESERVED_DEV_SKILLS_COUNT=0

  if [[ ! -d "${skills_dir}" ]]; then
    return 1
  fi

  local had_marker=0
  if [[ -f "${skills_dir}/.squad-ai-managed" || -f "$(dirname "${skills_dir}")/.squad-ai-manifest.json" ]]; then
    had_marker=1
  fi

  local -a to_remove=()
  for sk in "${SKILLS_CATALOG[@]}"; do
    local sk_dir="${skills_dir}/${sk}"
    local sk_md="${sk_dir}/SKILL.md"
    if [[ -f "${sk_md}" ]]; then
      local md_txt
      md_txt="$(<"${sk_md}")"
      if [[ "${md_txt}" == *"origin: squad-ai"* || "${md_txt}" == *"SquadAI Harness"* || "${md_txt}" == *"Linha de Defesa de Prompt"* ]]; then
        to_remove+=("${sk_dir}")
        LAST_REMOVED_SKILLS_COUNT=$((LAST_REMOVED_SKILLS_COUNT + 1))
      fi
    fi
  done

  if [[ ${#to_remove[@]} -gt 0 ]]; then
    rm -rf "${to_remove[@]}"
  fi

  rm -f "${skills_dir}/.squad-ai-managed" "$(dirname "${skills_dir}")/.squad-ai-manifest.json" 2>/dev/null || true

  local d
  for d in "${skills_dir}"/*; do
    if [[ -d "${d}" ]]; then
      LAST_PRESERVED_DEV_SKILLS_COUNT=$((LAST_PRESERVED_DEV_SKILLS_COUNT + 1))
    fi
  done

  if [[ ${LAST_PRESERVED_DEV_SKILLS_COUNT} -eq 0 && ${is_rai} -eq 0 ]]; then
    rmdir "${skills_dir}" 2>/dev/null || true
  fi

  if [[ ${LAST_REMOVED_SKILLS_COUNT} -gt 0 || ${had_marker} -eq 1 ]]; then
    return 0
  fi
  return 1
}

clean_managed_targets() {
  local removed=0
  for rel in "${TARGETS[@]}"; do
    local tskills="${USER_HOME}/${rel}/skills"
    if remove_squad_skills_from_dir "${tskills}" 0; then
      removed=$((removed + 1))
      if [[ "${1:-}" != "--silent" ]]; then
        echo "  ${C_YELLOW}[REMOVIDO]${C_RESET} ${tskills} (${LAST_REMOVED_SKILLS_COUNT} skills da SquadAI removidas; ${LAST_PRESERVED_DEV_SKILLS_COUNT} do dev preservadas)"
      fi
    fi
  done

  local rai_root
  rai_root="$(resolve_rai_root)"
  if [[ -d "${rai_root}/skills" ]]; then
    remove_squad_skills_from_dir "${rai_root}/skills" 1 || true
    rm -rf "${SQUAD_USER_DIR}/instalacoes/rai"
  fi
  return 0
}

